var i=`0571-sorpa`;var t=`world-0571`;var a=`KZ`;var o=`central-asia`;var r=4;var s=153;var m={en:`Sorpa`,ua:`Сорпа`};var g={en:`A traditional dish from Kazakhstan, centered on lamb, yellow onion, potato, carrot. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Казахстан. Основні складники: ягнятина, жовта цибуля, картопля, морква. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 120 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 120 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:120,i:[[`lamb`,750,`g`],[`water`,1700,`ml`],[`yellow-onion`,190,`g`],[`black-peppercorn`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`potato`,430,`g`],[`carrot`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var d={slug:i,id:t,country:`KZ`,region:o,servings:4,minutes:153,title:m,text:g,steps:l};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,i as slug,l as steps,g as text,m as title};